    def gameOfLife(self, board: List[List[int]]) -> None:
        R, C = len(board), len(board[0])
        for r in range(R):
            for c in range(C):
                live = sum(board[i][j] & 1 for i in range(max(0, r - 1), min(R, r + 2))
                           for j in range(max(0, c - 1), min(C, c + 2))) - (board[r][c] & 1)
