class Solution {
    public int subarraysDivByK(int[] nums, int k) {
        int[] cnt = new int[k];
        cnt[0] = 1;
        int pre = 0, res = 0;
        for (int x : nums) {
            pre = ((pre + x) % k + k) % k;
            res += cnt[pre]++;
        }
        return res;
